-- Pan Ocean (PANOCEAN) DG Prohibition List
-- Source: carriers/panocean.pdf  (PROHIBITED DANGEROUS GOODS LIST ON PANOCEAN FLEETS, Updated 20th AUG, 2026)
-- Effective from: 2026-08-20   (supersedes the 2023.03.28 edition)
-- New carrier registration: PANOCEAN was not previously present in dg_carrier_rules.
--
-- Status convention:
--   PROHIBITED  = the source lists the entry as prohibited (for PARTNERS, where the source distinguishes).
--   RESTRICTED  = conditionally acceptable - POL booking only, packaging / container condition,
--                 or an explicit acceptable exception to a Class-wide prohibition.
-- Entries marked "FOR PARTNERS: prohibited / POL BOOKING: conditional" are recorded as PROHIBITED
-- because Sinokor books as a partner; the POL-booking route is preserved in remark_text.
--
-- Run this in Supabase SQL Editor after reviewing the rows.

delete from public.dg_carrier_rules
where carrier_group = 'PANOCEAN';

